# System.Runtime.Intrinsics.Arm.AdvSimd — saturating and rounding arithmetic, and the
# shifts by a vector of per-lane counts (SSHL/USHL and their rounding/saturating
# forms: the count is a signed vector of the operand's width, negative meaning right).
# The logical forms are the unsigned intrinsic over the operand's bits. The 64-bit
# Scalar overloads operate on one-lane Vector64s, which the x1 intrinsics take whole.
AbsSaturate(v{W}{T}) = vqabs{q}_{neon}($0) for W in 64,128 for T in i8,i16,i32
AddSaturateScalar(v64{T},v64{T}) = vqadd_{neon}($0, $1) for T in i64,u64
MultiplyDoublingByScalarSaturateHigh(v{W}{T},v64{T}) = vqdmulh{q}_lane_{neon}($0, $1, 0) for W in 64,128 for T in i16,i32
MultiplyDoublingBySelectedScalarSaturateHigh(v{W}{T},v128{T},u8) @imm[0..{N128}) = vqdmulh{q}_laneq_{neon}($0, $1, $2) for W in 64,128 for T in i16,i32
MultiplyDoublingBySelectedScalarSaturateHigh(v{W}{T},v64{T},u8) @imm[0..{N64}) = vqdmulh{q}_lane_{neon}($0, $1, $2) for W in 64,128 for T in i16,i32
MultiplyDoublingSaturateHigh(v{W}{T},v{W}{T}) = vqdmulh{q}_{neon}($0, $1) for W in 64,128 for T in i16,i32
MultiplyRoundedDoublingByScalarSaturateHigh(v{W}{T},v64{T}) = vqrdmulh{q}_lane_{neon}($0, $1, 0) for W in 64,128 for T in i16,i32
MultiplyRoundedDoublingBySelectedScalarSaturateHigh(v{W}{T},v128{T},u8) @imm[0..{N128}) = vqrdmulh{q}_laneq_{neon}($0, $1, $2) for W in 64,128 for T in i16,i32
MultiplyRoundedDoublingBySelectedScalarSaturateHigh(v{W}{T},v64{T},u8) @imm[0..{N64}) = vqrdmulh{q}_lane_{neon}($0, $1, $2) for W in 64,128 for T in i16,i32
MultiplyRoundedDoublingSaturateHigh(v{W}{T},v{W}{T}) = vqrdmulh{q}_{neon}($0, $1) for W in 64,128 for T in i16,i32
NegateSaturate(v{W}{T}) = vqneg{q}_{neon}($0) for W in 64,128 for T in i8,i16,i32
ShiftArithmetic(v{W}{T},v{W}{T}) = vshl{q}_{neon}($0, $1) for W in 64,128 for T in i8,i16,i32
ShiftArithmetic(v128i64,v128i64) = vshlq_s64($0, $1)
ShiftArithmeticRounded(v{W}{T},v{W}{T}) = vrshl{q}_{neon}($0, $1) for W in 64,128 for T in i8,i16,i32
ShiftArithmeticRounded(v128i64,v128i64) = vrshlq_s64($0, $1)
ShiftArithmeticRoundedSaturate(v{W}{T},v{W}{T}) = vqrshl{q}_{neon}($0, $1) for W in 64,128 for T in i8,i16,i32
ShiftArithmeticRoundedSaturate(v128i64,v128i64) = vqrshlq_s64($0, $1)
ShiftArithmeticRoundedSaturateScalar(v64i64,v64i64) = vqrshl_s64($0, $1)
ShiftArithmeticRoundedScalar(v64i64,v64i64) = vrshl_s64($0, $1)
ShiftArithmeticSaturate(v{W}{T},v{W}{T}) = vqshl{q}_{neon}($0, $1) for W in 64,128 for T in i8,i16,i32
ShiftArithmeticSaturate(v128i64,v128i64) = vqshlq_s64($0, $1)
ShiftArithmeticSaturateScalar(v64i64,v64i64) = vqshl_s64($0, $1)
ShiftArithmeticScalar(v64i64,v64i64) = vshl_s64($0, $1)
ShiftLeftAndInsert(v{W}{T},v{W}{T},u8) @imm[0..{bits}) = vsli{q}_n_{neon}($0, $1, $2) for W in 64,128 for T in i8,u8,i16,u16,i32,u32
ShiftLeftAndInsert(v128{T},v128{T},u8) @imm[0..64) = vsliq_n_{neon}($0, $1, $2) for T in i64,u64
ShiftLeftAndInsertScalar(v64{T},v64{T},u8) @imm[0..64) = vsli_n_{neon}($0, $1, $2) for T in i64,u64
ShiftLeftLogicalSaturate(v{W}{T},u8) @imm[0..{bits}) = vqshl{q}_n_{neon}($0, $1) for W in 64,128 for T in i8,u8,i16,u16,i32,u32
ShiftLeftLogicalSaturate(v128{T},u8) @imm[0..64) = vqshlq_n_{neon}($0, $1) for T in i64,u64
ShiftLeftLogicalSaturateScalar(v64{T},u8) @imm[0..64) = vqshl_n_{neon}($0, $1) for T in i64,u64
ShiftLeftLogicalSaturateUnsigned(v{W}{T},u8) @imm[0..{bits}) = vqshlu{q}_n_{neon}($0, $1) for W in 64,128 for T in i8,i16,i32
ShiftLeftLogicalSaturateUnsigned(v128i64,u8) @imm[0..64) = vqshluq_n_s64($0, $1)
ShiftLeftLogicalSaturateUnsignedScalar(v64i64,u8) @imm[0..64) = vqshlu_n_s64($0, $1)
ShiftLeftLogicalScalar(v64{T},u8) @imm[0..64) = vshl_n_{neon}($0, $1) for T in i64,u64
ShiftLogical(v{W}{T},v{W}{sT}) = vshl{q}_{uT}($0:{uT}, $1) for W in 64,128 for T in i8,u8,i16,u16,i32,u32
ShiftLogical(v128{T},v128i64) = vshlq_u64($0:u64, $1) for T in i64,u64
ShiftLogicalRounded(v{W}{T},v{W}{sT}) = vrshl{q}_{uT}($0:{uT}, $1) for W in 64,128 for T in i8,u8,i16,u16,i32,u32
ShiftLogicalRounded(v128{T},v128i64) = vrshlq_u64($0:u64, $1) for T in i64,u64
ShiftLogicalRoundedSaturate(v{W}{T},v{W}{sT}) = vqrshl{q}_{uT}($0:{uT}, $1) for W in 64,128 for T in i8,u8,i16,u16,i32,u32
ShiftLogicalRoundedSaturate(v128{T},v128i64) = vqrshlq_u64($0:u64, $1) for T in i64,u64
ShiftLogicalRoundedSaturateScalar(v64{T},v64i64) = vqrshl_u64($0:u64, $1) for T in i64,u64
ShiftLogicalRoundedScalar(v64{T},v64i64) = vrshl_u64($0:u64, $1) for T in i64,u64
ShiftLogicalSaturate(v{W}{T},v{W}{sT}) = vqshl{q}_{uT}($0:{uT}, $1) for W in 64,128 for T in i8,u8,i16,u16,i32,u32
ShiftLogicalSaturate(v128{T},v128i64) = vqshlq_u64($0:u64, $1) for T in i64,u64
ShiftLogicalSaturateScalar(v64{T},v64i64) = vqshl_u64($0:u64, $1) for T in i64,u64
ShiftLogicalScalar(v64{T},v64i64) = vshl_u64($0:u64, $1) for T in i64,u64
ShiftRightAndInsert(v{W}{T},v{W}{T},u8) @imm[1..{bits}] = vsri{q}_n_{neon}($0, $1, $2) for W in 64,128 for T in i8,u8,i16,u16,i32,u32
ShiftRightAndInsert(v128{T},v128{T},u8) @imm[1..64] = vsriq_n_{neon}($0, $1, $2) for T in i64,u64
ShiftRightAndInsertScalar(v64{T},v64{T},u8) @imm[1..64] = vsri_n_{neon}($0, $1, $2) for T in i64,u64
ShiftRightArithmeticAdd(v{W}{T},v{W}{T},u8) @imm[1..{bits}] = vsra{q}_n_{neon}($0, $1, $2) for W in 64,128 for T in i8,i16,i32
ShiftRightArithmeticAdd(v128i64,v128i64,u8) @imm[1..64] = vsraq_n_s64($0, $1, $2)
ShiftRightArithmeticAddScalar(v64i64,v64i64,u8) @imm[1..64] = vsra_n_s64($0, $1, $2)
ShiftRightArithmeticRounded(v{W}{T},u8) @imm[1..{bits}] = vrshr{q}_n_{neon}($0, $1) for W in 64,128 for T in i8,i16,i32
ShiftRightArithmeticRounded(v128i64,u8) @imm[1..64] = vrshrq_n_s64($0, $1)
ShiftRightArithmeticRoundedAdd(v{W}{T},v{W}{T},u8) @imm[1..{bits}] = vrsra{q}_n_{neon}($0, $1, $2) for W in 64,128 for T in i8,i16,i32
ShiftRightArithmeticRoundedAdd(v128i64,v128i64,u8) @imm[1..64] = vrsraq_n_s64($0, $1, $2)
ShiftRightArithmeticRoundedAddScalar(v64i64,v64i64,u8) @imm[1..64] = vrsra_n_s64($0, $1, $2)
ShiftRightArithmeticRoundedScalar(v64i64,u8) @imm[1..64] = vrshr_n_s64($0, $1)
ShiftRightArithmeticScalar(v64i64,u8) @imm[1..64] = vshr_n_s64($0, $1)
ShiftRightLogicalAdd(v{W}{T},v{W}{T},u8) @imm[1..{bits}] = vsra{q}_n_{uT}($0:{uT}, $1:{uT}, $2) for W in 64,128 for T in i8,u8,i16,u16,i32,u32
ShiftRightLogicalAdd(v128{T},v128{T},u8) @imm[1..64] = vsraq_n_u64($0:u64, $1:u64, $2) for T in i64,u64
ShiftRightLogicalAddScalar(v64{T},v64{T},u8) @imm[1..64] = vsra_n_u64($0:u64, $1:u64, $2) for T in i64,u64
ShiftRightLogicalRounded(v{W}{T},u8) @imm[1..{bits}] = vrshr{q}_n_{uT}($0:{uT}, $1) for W in 64,128 for T in i8,u8,i16,u16,i32,u32
ShiftRightLogicalRounded(v128{T},u8) @imm[1..64] = vrshrq_n_u64($0:u64, $1) for T in i64,u64
ShiftRightLogicalRoundedAdd(v{W}{T},v{W}{T},u8) @imm[1..{bits}] = vrsra{q}_n_{uT}($0:{uT}, $1:{uT}, $2) for W in 64,128 for T in i8,u8,i16,u16,i32,u32
ShiftRightLogicalRoundedAdd(v128{T},v128{T},u8) @imm[1..64] = vrsraq_n_u64($0:u64, $1:u64, $2) for T in i64,u64
ShiftRightLogicalRoundedAddScalar(v64{T},v64{T},u8) @imm[1..64] = vrsra_n_u64($0:u64, $1:u64, $2) for T in i64,u64
ShiftRightLogicalRoundedScalar(v64{T},u8) @imm[1..64] = vrshr_n_u64($0:u64, $1) for T in i64,u64
ShiftRightLogicalScalar(v64{T},u8) @imm[1..64] = vshr_n_u64($0:u64, $1) for T in i64,u64
SubtractSaturateScalar(v64{T},v64{T}) = vqsub_{neon}($0, $1) for T in i64,u64
